# all vertical runs of 8
def runs(g,c):
    R=len(g);C=len(g[0]);res=[]
    for j in range(C):
        i=0
        while i<R:
            if g[i][j]==c:
                k=i
                while k<R and g[k][j]==c:k+=1
                if k-i>=3: res.append(('V',j,i,k-1))
                i=k
            else:i+=1
    for i in range(R):
        j=0
        while j<C:
            if g[i][j]==c:
                k=j
                while k<C and g[i][k]==c:k+=1
                if k-j>=3: res.append(('H',i,j,k-1))
                j=k
            else:j+=1
    return res
