import sys
sys.setrecursionlimit(100000)
def comps(g,c):
    R=len(g);C=len(g[0]);seen=set();res=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]==c and (i,j) not in seen:
                st=[(i,j)];seen.add((i,j));cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<R and 0<=y<C and g[x][y]==c and (x,y) not in seen:
                            seen.add((x,y));st.append((x,y))
                res.append(sorted(cells))
    return res
