def rots(sh):
    res=set()
    cur=sh
    for _ in range(4):
        mr=max(r for r,_ in cur); mc=max(c for _,c in cur)
        res.add(tuple(sorted(cur)))
        res.add(tuple(sorted((r,mc-c) for r,c in cur)))  # mirror
        cur=tuple(sorted((c,mr-r) for r,c in cur))  # rot90
    return res
